def dedupe_levels(apps, schema_editor):
    """A word may live in one level only. DE "das Angebot" existed in A2 and B2: the B2 row
    (supply) becomes "der Engpass" in place, so its ID is kept. The seed fills the new texts."""
    Word = apps.get_model("words", "Word")
    if Word.objects.filter(track="de", level="A2", word="Angebot", article="das").exists():
        Word.objects.filter(track="de", level="B2", word="Angebot", article="das").update(word="Engpass", article="der")


def term_key(term):
    return " ".join((term or "").strip().lower().split())


def backfill_found(apps, schema_editor):
    """Existing Leitner progress (box 5 = learned) on built-in words becomes found level words."""
    Word = apps.get_model("words", "Word")
    UserWord = apps.get_model("words", "UserWord")
    UserLevelWord = apps.get_model("words", "UserLevelWord")
    from django.utils import timezone

    index, by_id = {}, {}
    for w in Word.objects.all().only("id", "track", "level", "word", "article"):
        display = f"{w.article} {w.word}" if w.article else w.word
        index[(w.track, term_key(display))] = w
        by_id[w.id] = w
    now = timezone.now()
    rows, seen = [], set()
    for uw in UserWord.objects.filter(box__gte=5).iterator():
        w = by_id.get(uw.word_id) or index.get((uw.track, uw.term_key))
        if w is None or (uw.user_id, w.id) in seen:
            continue
        seen.add((uw.user_id, w.id))
        rows.append(
            UserLevelWord(user_id=uw.user_id, word_id=w.id, track=w.track, level=w.level, found_at=uw.last_seen_at or now)
        )
    UserLevelWord.objects.bulk_create(rows, ignore_conflicts=True, batch_size=1000)


